"""Guardrail tests for autogenerated wrapper request payload keys vs API spec."""

from __future__ import annotations

import ast
import json
from pathlib import Path

import pytest

REPO_ROOT = Path(__file__).resolve().parents[2]
API_CALLS_ROOT = REPO_ROOT / "src" / "britecore_sdk" / "api" / "api_calls"
SPEC_PATH = REPO_ROOT / "api_specs" / "current" / "britecore.json"
PROBE_REPORT_PATH = REPO_ROOT / "post_probe_report.json"


def _load_spec() -> dict:
    return json.loads(SPEC_PATH.read_text(encoding="utf-8"))


def _load_probe_fields() -> dict[str, set[str]]:
    """Return a map of API path -> probe-discovered required field names.

    Fields inferred from the probe run are considered valid even if the OpenAPI
    spec does not document them (the spec is incomplete for many endpoints).
    Returns an empty dict when the report file is absent.
    """
    if not PROBE_REPORT_PATH.exists():
        return {}
    report = json.loads(PROBE_REPORT_PATH.read_text(encoding="utf-8"))
    result: dict[str, set[str]] = {}
    for entry in report.get("results", []):
        path = entry.get("path", "")
        fields = entry.get("inferred_required_fields", [])
        if path and fields:
            result[path] = set(fields)
    return result


def _resolve_schema(schema: dict, components: dict) -> dict:
    ref = schema.get("$ref")
    if not isinstance(ref, str) or not ref.startswith("#/components/schemas/"):
        return schema
    schema_name = ref.rsplit("/", 1)[-1]
    return components.get("schemas", {}).get(schema_name, schema)


def _expected_request_keys(spec: dict, path: str, method: str) -> set[str]:
    operation = spec.get("paths", {}).get(path, {}).get(method.lower(), {})
    request_body = operation.get("requestBody", {})
    content = request_body.get("content", {})
    app_json = content.get("application/json", {})
    schema = app_json.get("schema", {})
    if not isinstance(schema, dict):
        return set()

    resolved = _resolve_schema(schema, spec.get("components", {}))
    properties = resolved.get("properties", {})
    if not isinstance(properties, dict):
        return set()
    return set(properties.keys())


def _extract_request_json_keys(function_node: ast.FunctionDef) -> set[str] | None:
    for node in function_node.body:
        value = None
        if isinstance(node, ast.AnnAssign) and isinstance(node.target, ast.Name):
            if node.target.id == "request_json":
                value = node.value
        elif isinstance(node, ast.Assign):
            for target in node.targets:
                if isinstance(target, ast.Name) and target.id == "request_json":
                    value = node.value
                    break

        if isinstance(value, ast.Dict):
            keys: set[str] = set()
            for key in value.keys:
                if isinstance(key, ast.Constant) and isinstance(key.value, str):
                    keys.add(key.value)
            return keys
    return None


def _iter_autogenerated_wrappers() -> list[tuple[Path, ast.FunctionDef, str, str]]:
    wrappers: list[tuple[Path, ast.FunctionDef, str, str]] = []

    for py_file in sorted(API_CALLS_ROOT.rglob("*.py")):
        if py_file.name == "__init__.py":
            continue

        tree = ast.parse(py_file.read_text(encoding="utf-8"))
        for node in tree.body:
            if not isinstance(node, ast.FunctionDef):
                continue

            doc = ast.get_docstring(node) or ""
            marker = "Autogenerated wrapper for ``"
            if marker not in doc:
                continue

            start = doc.find(marker)
            if start == -1:
                continue
            start += len(marker)
            end = doc.find("``", start)
            if end == -1:
                continue

            signature = doc[start:end]
            try:
                method, path = signature.split(" ", 1)
            except ValueError:
                continue
            wrappers.append((py_file, node, method.strip(), path.strip()))

    return wrappers


@pytest.mark.unit
def test_autogenerated_wrapper_request_keys_match_spec() -> None:
    """Autogenerated wrappers should send only spec-defined or probe-discovered fields.

    The OpenAPI spec is the primary source of truth for request field names.
    The probe report (``post_probe_report.json``) is a secondary source: fields
    inferred from validation-error responses are accepted as valid additions even
    when the spec does not document them (the spec is incomplete for many
    endpoints).

    A wrapper fails this check only when it sends fields that appear in neither
    the spec nor the probe report.
    """
    spec = _load_spec()
    probe_fields = _load_probe_fields()
    mismatches: list[str] = []

    for file_path, fn, method, path in _iter_autogenerated_wrappers():
        expected_keys = _expected_request_keys(spec, path, method)
        probe_keys = probe_fields.get(path, set())
        allowed_keys = expected_keys | probe_keys

        actual_keys = _extract_request_json_keys(fn)
        if actual_keys is None:
            continue

        # Keys the spec documents but the wrapper omits are a regression.
        # Extra keys (probe-discovered or manually curated) are acceptable because
        # the spec is known incomplete for many endpoints.
        missing_spec_keys = expected_keys - actual_keys

        if missing_spec_keys:
            mismatches.append(
                f"{file_path.relative_to(REPO_ROOT)}::{fn.name} ({method} {path})"
                f" spec={sorted(expected_keys)} probe={sorted(probe_keys)}"
                f" actual={sorted(actual_keys)}"
                + (f" missing={sorted(missing_spec_keys)}" if missing_spec_keys else "")
            )

    assert not mismatches, "\n".join(mismatches)

